/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isNumberArray = require( '@stdlib/assert/is-number-array' );
var isNonNegativeNumber = require( '@stdlib/assert/is-nonnegative-number' );
var format = require( '@stdlib/string/format' );

// MAIN //

/**
* Sets the axis label formate.
*
* @private
* @param {Array} value - boolean indicating whether to automatically re-render on a `change` event
* @throws {TypeError} must be a boolean
*/
function set( value ) {
	if ( isNonNegativeNumber( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s`non negative number is expected. Value: `%s`.', 'w-tic-spacing', value ) );
	}
	if ( this._axisDataObjs[ 2 ].count !== value ) {
		this._axisDataObjs[ 2 ].count = value;
		if ( !this._quite  ) {
			this.emit( 'change' );
		}
	}
}


// EXPORTS //

module.exports = set;
